{
  "tasks": [
    {
      "type": "cloze",
      "claim_id": "drilling-and-mud-logging-methods.c3",
      "question": "Заполните пропуск в описании фильтрационного метода",
      "text": "Фильтрационный метод позволяет оценить коллекторские свойства пород путем фиксации объема {{1}}, который поглощается пластом в процессе бурения.",
      "answers": [
        [
          "жидкости",
          "промывочной жидкости",
          "раствора"
        ]
      ],
      "explanation": "Фильтрационный метод основан на измерении поглощения промывочной жидкости, которая уходит в проницаемые пласты (коллекторы)."
    },
    {
      "type": "order",
      "claim_id": "drilling-and-mud-logging-methods.c7",
      "question": "Расставьте этапы изменения условий бурения по мере увеличения глубины",
      "items": [
        "Бурение на пресном глинистом растворе",
        "Уплотнение пород и рост глубины свыше 4—5 км",
        "Переход на использование технической или минерализованной воды",
        "Применение методов для сложных карбонатных коллекторов"
      ],
      "explanation": "С увеличением глубины (более 4-5 км) меняется тип промывочной жидкости и характер пород, что требует смены методики интерпретации."
    },
    {
      "type": "multi",
      "claim_id": "drilling-and-mud-logging-methods.c6",
      "question": "В каких условиях стандартные методы выделения межзерновых коллекторов (по данным АСПБ) наиболее эффективны?",
      "options": [
        "На глубинах до 4—5 км",
        "При использовании минерализованной воды",
        "В терригенных разрезах со слабой и средней уплотненностью",
        "В сильно уплотненных карбонатных породах"
      ],
      "answer": [
        0,
        2
      ],
      "explanation": "Метод эффективен для терригенных пород слабой/средней уплотненности на глубинах до 4-5 км при использовании пресного глинистого раствора."
    }
  ],
  "card": {
    "front": "Почему на глубинах свыше 4—5 км стандартные методы выделения межзерновых коллекторов становятся неэффективными?",
    "back": "Из-за высокой уплотненности пород и использования минерализованной промывочной жидкости, что требует применения методов для сложных карбонатных коллекторов."
  }
}
